"""Synthetic kernel faults, generated by walking the seams in the reference kernels.

Scoring an oracle against a published fault list has an obvious flaw: the list
is small, someone chose it, and any test policy can be tuned until it clears
that particular bar. The point of a mutation catalogue is to make the fault
population larger than anything a policy could be fitted to, and to generate it
from the structure of the operator rather than from a list of known answers.

Each entry perturbs exactly one aspect of a correct kernel, in a way a person or
a model plausibly would: a dropped factor, a rounded constant, a missing square
root, a padding lane filled with the wrong value, an accumulator that is
assigned rather than added to, a loop bound one step short.

The 10 faults the gpuemu corpus seeds by hand all appear here, because both are
parameterisations of the same kernels. They are marked `from_corpus` so the
scoring run can report them as a named subset.

Not every mutation is detectable. Rounding a constant in the sixth decimal place
may sit below every sensible tolerance at every shape, which makes it an
equivalent mutant in the mutation-testing sense: no oracle can be blamed for
missing it. The scoring harness measures viability first and excludes those,
because leaving them in would deflate every policy equally and hide the signal.
"""

from __future__ import annotations

import functools
from dataclasses import dataclass, field

from kernelverify.reference.kernels import KERNELS


@dataclass(frozen=True)
class Mutation:
    """One synthetic fault: a kernel plus the keywords that break it."""

    kernel: str
    params: dict
    label: str
    from_corpus: bool = False
    corpus_name: str = ""

    @property
    def name(self) -> str:
        args = ", ".join(f"{k}={v}" for k, v in self.params.items())
        return f"{self.kernel}[{args}]"

    def build(self):
        return functools.partial(KERNELS[self.kernel], **self.params)


def _m(kernel, params, label, corpus_name=""):
    return Mutation(kernel, params, label, bool(corpus_name), corpus_name)


CATALOGUE: list[Mutation] = [
    # -- GELU ---------------------------------------------------------------
    _m("gelu", {"leading_scale": 1.0}, "dropped the leading 0.5", "gelu_triton_buggy"),
    _m("gelu", {"leading_scale": 0.25}, "halved the leading factor twice"),
    _m("gelu", {"kappa": 1.0}, "dropped the sqrt(2/pi) factor"),
    _m("gelu", {"kappa": 0.8}, "rounded sqrt(2/pi) to one decimal"),
    _m("gelu", {"coeff": 0.0447}, "truncated the cubic coefficient"),
    _m("gelu", {"coeff": 0.5}, "wrong cubic coefficient"),
    # -- SiLU ---------------------------------------------------------------
    _m("silu", {"beta": 2.0}, "used Swish-beta=2 for SiLU", "silu_triton_buggy"),
    _m("silu", {"beta": 0.5}, "used Swish-beta=0.5 for SiLU"),
    _m("silu", {"beta": 1.702}, "used the GELU sigmoid approximation constant"),
    # -- LeakyReLU ----------------------------------------------------------
    _m("leaky_relu", {"alpha": 0.1}, "alpha 0.1 instead of 0.01", "leaky_relu_triton_buggy"),
    _m("leaky_relu", {"alpha": 0.2}, "alpha 0.2 instead of 0.01"),
    _m("leaky_relu", {"alpha": 0.0}, "collapsed LeakyReLU into ReLU"),
    _m("leaky_relu", {"alpha": 0.011}, "alpha off in the third decimal"),
    # -- RMSNorm ------------------------------------------------------------
    _m("rmsnorm", {"use_sqrt": False}, "dropped the square root", "rmsnorm_triton_buggy"),
    _m("rmsnorm", {"eps": 0.0}, "dropped the epsilon"),
    _m("rmsnorm", {"eps": 1e-3}, "epsilon two orders too large"),
    _m("rmsnorm", {"divisor_offset": -1}, "off by one in the element count"),
    # -- L2 norm ------------------------------------------------------------
    _m("l2norm", {"use_sqrt": False}, "dropped the square root", "l2norm_triton_buggy"),
    _m("l2norm", {"eps": 1e-6}, "epsilon six orders too large"),
    # -- Softmax, block tiled ------------------------------------------------
    _m("softmax", {"pad_fill": 0.0}, "padding lanes load 0.0 not -inf", "softmax_triton_buggy"),
    _m("softmax", {"pad_fill": -1e9}, "padding lanes load a large negative not -inf"),
    _m("softmax", {"subtract_max": False}, "dropped the max subtraction"),
    # -- Softmax, padded to a fixed multiple ---------------------------------
    _m("softmax_padded", {"mask_tail": False}, "padded zeros left in the denominator",
       "softmax_llm_buggy"),
    _m("softmax_padded", {"mask_tail": False, "block": 64}, "same, tiled at 64"),
    _m("softmax_padded", {"mask_tail": False, "block": 256}, "same, tiled at 256"),
    # -- Matmul --------------------------------------------------------------
    _m("matmul", {"accumulate": False}, "assigned instead of accumulating",
       "matmul_triton_buggy"),
    _m("matmul", {"k_offset": -1}, "reduction loop one step short"),
    # -- Attention -----------------------------------------------------------
    _m("attention", {"scale_power": 0.0}, "dropped the 1/sqrt(D) scale",
       "attention_triton_buggy"),
    _m("attention", {"scale_power": -1.0}, "scaled by 1/D instead of 1/sqrt(D)"),
    _m("attention", {"scale_power": -0.25}, "scaled by D^-0.25"),
    _m("attention", {"subtract_max": False}, "dropped the max subtraction"),
    # -- Flash attention ------------------------------------------------------
    _m("flash_attention", {"rescale_acc": False}, "dropped the accumulator rescale",
       "flash_attention_triton_buggy"),
    _m("flash_attention", {"rescale_norm": False}, "dropped the normaliser rescale"),
    _m("flash_attention", {"scale_power": 0.0}, "dropped the 1/sqrt(D) scale"),
    _m("flash_attention", {"scale_power": -1.0}, "scaled by 1/D instead of 1/sqrt(D)"),
    # -- Second wave: mechanisms the published corpus never seeded ------------
    # Wrong-function-variant drift, near tolerance rather than gross.
    _m("gelu", {"variant": "erf"}, "implemented the erf GELU against a tanh reference"),
    # Wrong exponent base: the tl.exp2 confusion.
    _m("softmax", {"exp_base2": True}, "computed 2^x instead of e^x"),
    # Cross-row contamination from an off-by-one load mask.
    _m("softmax", {"read_past_row": True}, "mask off by one reads into the next row"),
    # Precision fault whose error grows with the reduction, inverse of dilution.
    _m("matmul", {"accum_dtype": "float16"}, "accumulated at fp16 instead of fp32"),
    # Purely numerical fault: only expresses when exp underflows a whole row.
    _m("flash_attention", {"init_max_zero": True}, "running max started at 0 not -inf"),
    # Operation-order transposition rather than a wrong constant.
    _m("attention", {"post_scale": True}, "scale applied after the softmax"),
    # Epsilon placement: expected to be equivalent at these magnitudes.
    _m("rmsnorm", {"eps_outside": True}, "epsilon added outside the sqrt"),
    # Dropped epsilon on a sum that is never zero: expected equivalent.
    _m("l2norm", {"eps": 0.0}, "dropped the epsilon"),
    # Boundary comparison rewrite: provably equivalent, tests the exclusion.
    _m("leaky_relu", {"boundary_ge": True}, "x >= 0 instead of x > 0"),
    # Precision canary (ADR 0004): scores kept in fp16. A conditioning-aware
    # tolerance must keep catching this, or it has legitimised the very
    # precision faults the verifier exists to reject.
    _m("attention", {"scores_dtype": "float16"}, "score matrix held at fp16"),
]


# Which corpus operator supplies the schema, reference and tolerances for each
# kernel. The corpus has no separate schema for the padded softmax variant, so
# it borrows the block-tiled softmax one, which is the same operator.
KERNEL_TO_CORPUS_OP = {
    "gelu": "gelu_triton",
    "silu": "silu_triton",
    "leaky_relu": "leaky_relu_triton",
    "rmsnorm": "rmsnorm_triton",
    "l2norm": "l2norm_triton",
    "softmax": "softmax_triton",
    "softmax_padded": "softmax_triton",
    "matmul": "matmul_triton",
    "attention": "attention_triton",
    "flash_attention": "flash_attention_triton",
}


def by_kernel() -> dict[str, list[Mutation]]:
    grouped: dict[str, list[Mutation]] = {}
    for mutation in CATALOGUE:
        grouped.setdefault(mutation.kernel, []).append(mutation)
    return grouped
